  "None of your battle reports has been read yet. Share one in the clan chat, or send it to the scanner account in a private message; it is read within a few minutes.": "Aucun de vos rapports de bataille n’a encore été lu. Partagez-en un dans le chat du clan, ou envoyez-le au compte scanner en message privé ; il est lu en quelques minutes.",
