  "Review": "À vérifier",
  "Members": "Membres",
  "Admin access required.": "Accès administrateur requis.",
  "Nothing needs review right now.": "Rien à vérifier pour le moment.",
  "The member list could not be loaded.": "La liste des membres n’a pas pu être chargée.",
  "Rename, remove or restore members. Renames in the game follow on their own.": "Renommez, retirez ou rétablissez des membres. Les changements de nom dans le jeu suivent d'eux-mêmes.",
  "Edit Members ({count})": "Modifier les membres ({count})",
  "Show member list": "Afficher la liste des membres",
  "Rename or remove members. Removing a player who has chest history keeps their existing records but excludes them from future scans — useful when a player leaves so a new player with a similar name can't accidentally be matched into their identity.": "Renommez ou retirez des membres. Retirer un joueur qui a un historique de coffres conserve ses enregistrements existants mais l'exclut des scans futurs — utile quand un joueur part, pour qu'un nouveau joueur au nom proche ne soit pas associé par erreur à son identité.",
  "Current Name": "Nom actuel",
  "New Name": "Nouveau nom",
  "Current": "Actuel",
  "Remove": "Retirer",
  "Show removed members ({count})": "Afficher les membres retirés ({count})",
  "Players excluded from scan matching. Their chest history is intact. Restore one if it was removed by mistake or the player rejoined the clan.": "Joueurs exclus de la reconnaissance des scans. Leur historique de coffres est intact. Restaurez-en un s'il a été retiré par erreur ou s'il a rejoint le clan à nouveau.",
  "Last Seen": "Vu en dernier",
  "Restore": "Restaurer",
  "Triumphal Chest Points": "Points des coffres triomphaux",
  "One <strong>global scoring table</strong> for the <strong>Bank Gifts</strong> tab, tracked separately from the main leaderboard. Each value is the <strong>package price</strong> (a full 3-of-a-kind set); a single chest is worth one third of it, rounded — so three of a kind sum back to exactly the package value. Rows tagged {new} have been seen in scans but have <strong>no value yet</strong> (they score 0) — set a value to score them.": "Un <strong>barème global</strong> pour l'onglet <strong>Cadeaux de banque</strong>, suivi séparément du classement principal. Chaque valeur est le <strong>prix du pack</strong> (un lot complet de 3 identiques) ; un coffre seul vaut un tiers de ce prix, arrondi — trois identiques redonnent donc exactement la valeur du pack. Les lignes marquées {new} ont été vues dans les scans mais n'ont <strong>pas encore de valeur</strong> (elles valent 0) — définissez une valeur pour les compter.",
  "New": "Nouveau",
  "Managed here by superadmins; values apply to every clan.": "Géré ici par les superadmins ; les valeurs s'appliquent à tous les clans.",
  "<strong>Read-only</strong> — only a superadmin can change these values.": "<strong>Lecture seule</strong> — seul un superadmin peut modifier ces valeurs.",
  "Show triumphal chest values ({count})": "Afficher les valeurs des coffres triomphaux ({count})",
  "Chests Seen": "Coffres vus",
  "Per Chest": "Par coffre",
  "Package (3-of-a-kind)": "Pack (3 identiques)",
  "Seen in scans but has no point value yet — it currently scores 0. Set a package value to score it.": "Vu dans les scans mais sans valeur en points — il vaut actuellement 0. Définissez une valeur de pack pour le compter.",
  "{n} seen": { one: "{n} vu", other: "{n} vus" },
  "Save All Changes": "Enregistrer tout",
  "Saves every chest whose package value changed. Clear an input to remove that chest's value — it reverts to \"new\" and scores 0 until set again. Points are presentation-only, so no historical backfill is needed.": "Enregistre chaque coffre dont la valeur de pack a changé. Videz un champ pour supprimer la valeur de ce coffre — il repasse en \"new\" et vaut 0 jusqu'à nouvelle définition. Les points ne servent qu'à l'affichage : aucun recalcul de l'historique n'est nécessaire.",
  "No triumphal chest data yet.": "Aucune donnée de coffre triomphal pour l'instant.",
  "\"{chest}\" must be a non-negative integer": "\"{chest}\" doit être un entier positif ou nul",
  "No changes to save.": "Aucun changement à enregistrer.",
  "Nothing to do": "Rien à faire",
  "Some changes failed:\n{errors}": "Certains changements ont échoué :\n{errors}",
  "Partial save": "Enregistrement partiel",
  "Saved {n} changes.": { one: "{n} changement enregistré.", other: "{n} changements enregistrés." },
  "Saved": "Enregistré",
  "New Triumphal Chests": "Nouveaux coffres triomphaux",
  "Chest Name": "Nom du coffre",
  "First Seen": "Vu en premier",
  "Assign each a package value under {link} on the Points tab — that scores them and clears them from this list.": "Attribuez à chacun une valeur de pack dans {link}, onglet Points — cela les compte et les retire de cette liste.",
  "Rename failed": "Échec du renommage",
  "this member": "ce membre",
  "Remove {member}? Their chest history stays intact, but they'll be excluded from future scans so a new player with a similar name can't get matched into their identity. You can restore them later under Admin → Members → \"Show removed members\".": "Retirer {member} ? Son historique de coffres reste intact, mais il sera exclu des scans futurs afin qu'un nouveau joueur au nom proche ne puisse pas être associé à son identité. Vous pourrez le restaurer plus tard via Administration → Membres → « Afficher les membres retirés ».",
  "Remove member": "Retirer le membre",
  "Remove member failed": "Échec du retrait du membre",
