  "Share of their points that came from their single biggest day. Context, not a verdict — concentrating a week's effort into an event day is a normal way to play.": "Part de leurs points venant de leur meilleure journée. Un contexte, pas un jugement — concentrer l'effort d'une semaine sur un jour d'événement est une façon normale de jouer.",
