  "Not shown for this window: the scanner was quiet for {n} hours, longer than a gift survives, so a member looking inactive here may just be a chest nobody could capture.": { one: "Non affiché pour cette fenêtre : le scanner est resté inactif {n} heure, plus longtemps que la durée de vie d'un cadeau ; un membre qui semble inactif ici peut simplement avoir un coffre que personne n'a pu capturer.", other: "Non affiché pour cette fenêtre : le scanner est resté inactif {n} heures, plus longtemps que la durée de vie d'un cadeau ; un membre qui semble inactif ici peut simplement avoir un coffre que personne n'a pu capturer." },
