  "None of the {n} chests in this timeframe carry a real earn time, so there is nothing to place on a clock. They were recorded before receive times were captured and only have their scan time.": { one: "Le {n} coffre de cette période n'a pas d'heure d'obtention réelle, il n'y a donc rien à placer sur une horloge. Il a été enregistré avant que les heures de réception ne soient relevées et n'a que l'heure du scan.", other: "Aucun des {n} coffres de cette période n'a d'heure d'obtention réelle, il n'y a donc rien à placer sur une horloge. Ils ont été enregistrés avant que les heures de réception ne soient relevées et n'ont que l'heure du scan." },
  "Only {count} of {n} chests in this timeframe carry a real earn time — too few to read a pattern from without inventing one.": { one: "Seuls {count} coffre sur {n} de cette période ont une heure d'obtention réelle — trop peu pour dégager une tendance sans en inventer une.", other: "Seuls {count} coffres sur {n} de cette période ont une heure d'obtention réelle — trop peu pour dégager une tendance sans en inventer une." },
