  "Page {page} of {pages}": "Page {page} sur {pages}",
  "The Tin Man hits could not be loaded.": "Les attaques contre le Tin Man n’ont pas pu être chargées.",
  "Read from battle reports shared in the clan chat, sent in a private message to the scanner account, or shared in a chat picked under Clans → In-game. A hit nobody shared is not here.": "Lu dans les rapports de bataille partagés dans le chat du clan, envoyés en message privé au compte scanner ou partagés dans un chat choisi sous Clans → En jeu. Une attaque que personne n’a partagée n’apparaît pas ici.",
  "The Tin Man starts with 4 stacks of monsters and drops to 3, 2 and 1 as it loses health. The stacks are the ones it had when the hit began.": "Le Tin Man commence avec 4 piles de monstres et descend à 3, 2 puis 1 en perdant de la santé. Les piles sont celles qu’il avait au début de l’attaque.",
  "No Tin Man rule is set for the clan, so hits are held to 4 stacks. An admin can set another under Clans → In-game → Battle reports.": "Aucune règle Tin Man n’est définie pour le clan : les attaques sont jugées à 4 piles. Un admin peut en définir une autre sous Clans → En jeu → Rapports de bataille.",
  "{n} shared reports are still being read.": { one: "{n} rapport partagé est encore en cours de lecture.", other: "{n} rapports partagés sont encore en cours de lecture." },
  "{n} hits by players outside the clan’s roster are only in the list of every hit.": { one: "{n} attaque d’un joueur hors de l’effectif du clan ne figure que dans la liste de toutes les attaques.", other: "{n} attaques de joueurs hors de l’effectif du clan ne figurent que dans la liste de toutes les attaques." },
