  "The vaults could not be loaded.": "Les Chambres Fortes n’ont pas pu être chargées.",
  "The map around the clan has not been read yet.": "La carte autour du clan n’a pas encore été lue.",
  "Vaults are read from the map since {date}, after this run.": "Les Chambres Fortes sont lues sur la carte depuis le {date}, après cette édition.",
  "A vault goes up within about 10 squares of the city of the member who raised it, on the first day of the run. Each scan reads the map there.": "Une Chambre Forte apparaît à environ 10 cases de la ville du membre qui l’a dressée, le premier jour de l’édition. Chaque scan lit la carte à cet endroit.",
  "A vault taken down before the next scan is not seen.": "Une Chambre Forte abattue avant le scan suivant n’est pas vue.",
  "Vault links are read from {chats}. A link counts for the member who posted it, and is matched to the map by tile, level and time.": "Les liens de chambres fortes sont lus dans {chats}. Un lien compte pour le membre qui l’a publié, et est rapproché de la carte par case, niveau et heure.",
  "Pick the chat where members link their vaults under Clans → In-game → Battle reports, and this shows who posted theirs.": "Choisissez sous Clans → En jeu → Rapports de bataille le chat où les membres publient le lien de leur chambre forte, et ceci montrera qui a publié la sienne.",
  "{n} vaults raised by players outside the clan were also seen nearby.": { one: "{n} Chambre Forte dressée par un joueur hors du clan a aussi été vue à proximité.", other: "{n} Chambres Fortes dressées par des joueurs hors du clan ont aussi été vues à proximité." },
  "No vault raised by a member was seen in this timeframe.": "Aucune Chambre Forte dressée par un membre n’a été vue sur cette période.",
  "{n} posted vaults were not seen on the map: raised out of the map pass’s reach, or taken down before a scan.": { one: "{n} chambre forte publiée n’a pas été vue sur la carte : érigée hors de portée de la lecture de la carte, ou détruite avant un scan.", other: "{n} chambres fortes publiées n’ont pas été vues sur la carte : érigées hors de portée de la lecture de la carte, ou détruites avant un scan." },
