  "On": "Activé",
  "Dry run": "Essai",
  "Off": "Désactivé",
  "Chat sending is switched off on this server (CHAT_SEND_DISABLED): nothing is answered.": "L'envoi dans le chat est désactivé sur ce serveur (CHAT_SEND_DISABLED) : rien n'est répondu.",
  "The scanner account isn't known yet; it is read at the clan's next scan.": "Le compte scanner n'est pas encore connu ; il sera lu au prochain scan du clan.",
  "The game muted the scanner account’s chat at {at}. Nothing is sent until {until}; codes wait and go out after that.": "Le jeu a rendu muet le chat du compte scanner à {at}. Rien n’est envoyé avant {until} ; les codes attendent et partent ensuite.",
  "On since {date}": "Activé depuis le {date}",
  "{n} linked accounts in this clan.": { one: "{n} compte lié dans ce clan.", other: "{n} comptes liés dans ce clan." },
  "Answer code requests": "Répondre aux demandes de code",
  "A member messages the scanner account “code” in the game and gets one back.": "Un membre écrit « code » au compte scanner dans le jeu et en reçoit un.",
  "Send members a code": "Envoyer un code aux membres",
  "The scanner account messages each member without an account once, then everyone who joins. One message every 10 minutes at most.": "Le compte scanner écrit une fois à chaque membre sans compte, puis à chaque nouvel arrivant. Au plus un message toutes les 10 minutes.",
  "Not tried live yet. Dry run lists who would get a code and sends nothing.": "Pas encore essayé en conditions réelles. L’essai liste qui recevrait un code et n’envoie rien.",
  "Messages name the site as {site}.": "Les messages désignent le site comme {site}.",
  "No public address is set, so messages say “the TB Chest Counter site”.": "Aucune adresse publique n’est définie : les messages disent « le site TB Chest Counter ».",
  "Edit": "Modifier",
  "Site name in messages (every clan)": "Nom du site dans les messages (tous les clans)",
  "Every clan. Leave it as the public address unless the game should see another name.": "Pour tous les clans. Gardez l’adresse publique, sauf si le jeu doit voir un autre nom.",
  "Words that ask for a code: {words}": "Mots qui demandent un code : {words}",
  "Only members on the roster get a code. It lasts 72 hours, works once, and a player gets at most one every 10 minutes.": "Seuls les membres du clan reçoivent un code. Il dure 72 heures, sert une fois, et un joueur en reçoit au plus un toutes les 10 minutes.",
  "The scanner account sends the codes, so its own player never gets one.": "Le compte scanner envoie les codes, son propre joueur n’en reçoit donc jamais.",
  "On the Join page the code creates their account linked to their player, sets a new password, or adds this clan to their account.": "Sur la page d’inscription, le code crée leur compte lié à leur joueur, définit un nouveau mot de passe ou ajoute ce clan à leur compte.",
  "Roles follow the game: the {leader} and {superior} ranks are admins here, everyone else a member. Someone who leaves the clan in the game loses access until they are back.": "Les rôles suivent le jeu : les rangs {leader} et {superior} sont admins ici, tous les autres membres. Qui quitte le clan dans le jeu perd l'accès jusqu'à son retour.",
  "The game blocks links, so messages spell the site out and tell players to pick “{label}”.": "Le jeu bloque les liens : les messages écrivent le site en toutes lettres et disent de choisir « {label} ».",
  "Have a code? Join here": "Vous avez un code ? Rejoindre ici",
  "{n} members would get a code": { one: "{n} membre recevrait un code", other: "{n} membres recevraient un code" },
  "Dry run: nothing is sent. Switch to On to send these, one every 10 minutes.": "Essai : rien n’est envoyé. Passez sur Activé pour les envoyer, un toutes les 10 minutes.",
  "Codes for members": "Codes pour les membres",
  "Account": "Compte",
  "Recent code requests": "Demandes de code récentes",
  "Asked": "Demandé",
  "Players get a one-time code from the scanner account, {name}, in the game chat, and enter it on the site to get an account linked to their player.": "Les joueurs reçoivent un code à usage unique du compte scanner, {name}, dans le chat du jeu et le saisissent sur le site pour obtenir un compte lié à leur joueur.",
  "Players get a one-time code from the scanner account in the game chat, and enter it on the site to get an account linked to their player.": "Les joueurs reçoivent un code à usage unique du compte scanner dans le chat du jeu et le saisissent sur le site pour obtenir un compte lié à leur joueur.",
  "The scanner account will message {n} members a code, one every 10 minutes.": { one: "Le compte scanner enverra un code à {n} membre, un toutes les 10 minutes.", other: "Le compte scanner enverra un code à {n} membres, un toutes les 10 minutes." },
  "Switch on": "Activer",
  "Save failed: {error}": "Échec de l'enregistrement : {error}",
  "Saved.": "Enregistré.",
  "Save failed.": "Échec de l'enregistrement.",
  "Choose a player…": "Choisissez un joueur…",
  "Have an account (the code sets a new password)": "Ont déjà un compte (le code définit un nouveau mot de passe)",
  "Have an account already": "Ont déjà un compte",
  "Code for {player}": "Code pour {player}",
  "Works once, until {date}. Copy it now: it is not shown again once you leave this page.": "Valable une fois, jusqu’au {date}. Copiez-le maintenant : il n’est plus affiché une fois cette page quittée.",
  "{player} already has an account ({account}): this code sets a new password for it.": "{player} a déjà un compte ({account}) : ce code lui définit un nouveau mot de passe.",
  "Copy code": "Copier le code",
  "Copy message": "Copier le message",
  "Give it only to {player}: whoever uses it becomes this player on the site. The message is in English and has no link, so it can go in the game chat too.": "Ne le donnez qu’à {player} : quiconque l’utilise devient ce joueur sur le site. Le message est en anglais et sans lien, il peut donc aussi aller dans le chat du jeu.",
  "Used by {account}": "Utilisé par {account}",
  "Used": "Utilisé",
  "Code expired": "Code expiré",
  "Works until {date}": "Valable jusqu’au {date}",
  "Codes made here": "Codes créés ici",
  "Made by": "Créé par",
  "Made": "Créé",
  "Actions": "Actions",
  "Withdraw": "Retirer",
  "Make a code yourself": "Créer un code vous-même",
  "For when the scanner account can’t send one — muted, or the player doesn’t read the chat. You pass the code on; it works the same: 72 hours, once, only for that player.": "Pour quand le compte scanner ne peut pas en envoyer — rendu muet, ou le joueur ne lit pas le chat. Vous transmettez le code ; il fonctionne de la même façon : 72 heures, une fois, seulement pour ce joueur.",
  "Make code": "Créer le code",
  "The roster is read at the clan’s next scan.": "La liste des membres est lue au prochain scan du clan.",
  "Could not make a code: {error}": "Impossible de créer le code : {error}",
  "Withdraw this code? It stops working at once.": "Retirer ce code ? Il cesse de fonctionner immédiatement.",
  "Could not withdraw the code: {error}": "Impossible de retirer le code : {error}",
  "{n} current members without an account would get one first.": { one: "{n} membre actuel sans compte en recevrait un en premier.", other: "{n} membres actuels sans compte en recevraient un en premier." },
  "Codes sent: {sent} of {total}": "Codes envoyés : {sent} sur {total}",
  "{n} could not be sent": { one: "{n} n'a pas pu être envoyé", other: "{n} n'ont pas pu être envoyés" },
  "Not used yet": "Pas encore utilisé",
