  "The scanner account, {name}, is {rank} in the clan. Only a {leader} or {superior} can send from the treasury, so nothing is sent.": "Le compte du scanner, {name}, est {rank} dans le clan. Seul un {leader} ou un {superior} peut envoyer depuis le trésor, donc rien n’est envoyé.",
