  "{n} sends in the last 7 days": { one: "{n} envoi ces 7 derniers jours", other: "{n} envois ces 7 derniers jours" },
  "Send {coins} back automatically": "Rendre les {coins} automatiquement",
  "Only coins that reach the treasury after this is switched on. What the clan itself wins in an event is never sent.": "Seulement les pièces qui arrivent au trésor après l’activation. Ce que le clan gagne lui-même lors d’un événement n’est jamais envoyé.",
  "Waiting to be sent": "En attente d’envoi",
  "Sent after the clan’s next scan.": "Envoyé après le prochain scan du clan.",
  "Arrived": "Arrivé",
  "Nothing waiting: every member’s coins since the switch went on have been sent back.": "Rien en attente : les pièces de chaque membre depuis l’activation ont été rendues.",
  "Left in the treasury": "Laissé au trésor",
  "Only coins a member brings in: when they collect an event reward, the game sends its {coins} to the treasury under their name. What the clan wins (credited to the {leader} at the reset) is never sent.": "Seulement les pièces qu’un membre apporte : quand il récupère une récompense d’événement, le jeu envoie ses {coins} au trésor à son nom. Ce que gagne le clan (crédité au {leader} à la réinitialisation) n’est jamais envoyé.",
  "Only coins that arrive after the switch goes on. Switching it off and on again starts from then.": "Seulement les pièces qui arrivent après l’activation. Désactiver puis réactiver repart de ce moment-là.",
  "One send per member with all their waiting coins, up to {perRun} members a scan, never more than the treasury holds.": "Un envoi par membre avec toutes ses pièces en attente, jusqu’à {perRun} membres par scan, jamais plus que ce que contient le trésor.",
  "Coins a {leader} or {superior} already paid back by hand (the same amount to that member after the coins arrived) are not sent again.": "Les pièces qu’un {leader} ou un {superior} a déjà rendues à la main (le même montant à ce membre après leur arrivée) ne sont pas renvoyées.",
  "Every send is checked in the treasury history. One that doesn’t show there within {minutes} minutes is tried again, at most {attempts} times.": "Chaque envoi est vérifié dans l’historique du trésor. Un envoi qui n’y apparaît pas sous {minutes} minutes est retenté, au plus {attempts} fois.",
  "Coins of a member who left the clan stay in the treasury.": "Les pièces d’un membre qui a quitté le clan restent au trésor.",
  "Recent sends": "Envois récents",
  "When a member collects an event reward, its {coins} go to the clan treasury. With this on, the scanner account sends each member theirs back after the scan that sees them arrive.": "Quand un membre récupère une récompense d’événement, ses {coins} vont au trésor du clan. Avec ceci activé, le compte du scanner rend à chaque membre les siennes après le scan qui les voit arriver.",
  // pages/clan-roster.js
  "Joins": "Arrivées",
  "Leaves": "Départs",
  "as {name}": "sous le nom {name}",
  "{name} came back to the clan": "{name} est revenu dans le clan",
  "left {date}": "parti le {date}",
  "in the clan before: first seen {date}": "déjà dans le clan : vu la première fois le {date}",
  "{name} was restored on the site": "{name} a été restauré sur le site",
  "{name} marked as left": "{name} marqué comme parti",
  "The site's record, not the game's: the day it marked them gone, which can be later than the day they left.": "Relevé du site, pas du jeu : le jour où il l'a marqué comme parti, qui peut être postérieur au jour du départ.",
  "{n} joins": { one: "{n} arrivée", other: "{n} arrivées" },
