  "{n} returns": { one: "{n} retour", other: "{n} retours" },
  "{joined} · {left} in the last {days} days": "{joined} · {left} sur les {days} derniers jours",
  "Join times are the game's own, read since {date}: anyone who left before then shows only when they left. “Marked as left” is the site's own record from before the game was read: the day it noticed, which can be later than the day they left.": "Les dates d'arrivée sont celles du jeu, lues depuis le {date} : quiconque est parti avant n'apparaît qu'à son départ. « Marqué comme parti » est le relevé du site lui-même d'avant la lecture du jeu : le jour où il l'a remarqué, qui peut être postérieur au jour du départ.",
  "The clan's roster hasn't been read from the game yet. The next scan reads it.": "La liste des membres du clan n'a pas encore été lue dans le jeu. Le prochain scan la lit.",
