  "Every {n} days, from {date}": { one: "Tous les {n} jour, depuis le {date}", other: "Tous les {n} jours, depuis le {date}" },
  "Sunday to Sunday (7 days)": "De dimanche à dimanche (7 jours)",
  "Pick any day one of the weeks starts on, and how many days each lasts. Weeks start at the daily reset, {time}.": "Choisissez n’importe quel jour où commence une des semaines, et combien de jours chacune dure. Les semaines commencent à la réinitialisation quotidienne, à {time}.",
  "Pick the day a week starts on, and a length of {min}–{max} days.": "Choisissez le jour où commence une semaine, et une durée de {min} à {max} jours.",
  "This week: <strong>{range}</strong>. The next one starts {date}.": "Cette semaine : <strong>{range}</strong>. La suivante commence le {date}.",
  "In a Seasonal Kingdom, Tinman to Tinman opens when {event} ({ancients} day 2) begins at 17:00 UTC and runs until the next one begins, {n} days later.": { one: "Dans un Royaume saisonnier, la semaine de Tinman à Tinman commence quand {event} (jour 2 de {ancients}) démarre à 17:00 UTC et dure jusqu’au démarrage du suivant, {n} jour plus tard.", other: "Dans un Royaume saisonnier, la semaine de Tinman à Tinman commence quand {event} (jour 2 de {ancients}) démarre à 17:00 UTC et dure jusqu’au démarrage du suivant, {n} jours plus tard." },
  "Tinman to Tinman opens when {event} ({ancients} day 2) begins at 17:00 UTC and runs until the next one begins, six days later.": "La semaine Tinman à Tinman commence quand {event} ({ancients} jour 2) débute à 17:00 UTC et dure jusqu'au début du suivant, six jours plus tard.",
