  "Add Clan": "Ajouter un clan",
  "Each clan has its own member roster, chest data, Total Battle login, Discord channel, and ChestTracker share code. The scanner reads every active clan in turn on each scheduled interval.": "Chaque clan a son propre effectif, ses données de coffres, sa connexion Total Battle, son salon Discord et son code de partage ChestTracker. Le scanner lit chaque clan actif l'un après l'autre à chaque intervalle planifié.",
  "Manage your clan's Discord and ChestTracker integrations and refresh the Total Battle login session.": "Gérez les intégrations Discord et ChestTracker de votre clan et actualisez la session de connexion Total Battle.",
