  "e.g. Arcane Dawn": "ex. Arcane Dawn",
  "Create": "Créer",
  "After creating, sign in to TB for the new clan via the in-app login bridge. The next scan reads its members and chests from the game.": "Après la création, connectez-vous à TB pour le nouveau clan via la connexion à distance intégrée. Le scan suivant lit ses membres et ses coffres dans le jeu.",
