  // pages/member-profile.js
  "Might is the game’s measure of a player’s total strength: army, buildings, research and heroes together.": "La puissance est la mesure du jeu de la force totale d’un joueur : armée, bâtiments, recherche et héros réunis.",
  "The Gold Pass is the game’s paid monthly pass. The game reports who has it.": "Le Pass d’or est le pass mensuel payant du jeu. Le jeu indique qui l’a.",
  "Clan ranks in the game, highest first: {ranks}. The {leader} and {superior} ranks run the clan, and are admins on this site too.": "Rangs du clan dans le jeu, du plus haut : {ranks}. Les rangs {leader} et {superior} dirigent le clan et sont aussi admins sur ce site.",
  "The highest Guardsmen troop tier this player has researched: G1 is the first, each tier is stronger.": "Le plus haut palier de Gardes que ce joueur a recherché : G1 est le premier, chaque palier est plus fort.",
  "Crypts are places on the game map that players explore. Each one explored sends a chest to the clan’s Gifts with the player’s name on it.": "Les cryptes sont des lieux de la carte que les joueurs explorent. Chacune explorée envoie un coffre dans les Cadeaux du clan, au nom du joueur.",
  "Citadels are strongholds on the map that clan members attack. A win sends chests to the clan’s Gifts.": "Les citadelles sont des forteresses de la carte que les membres du clan attaquent. Une victoire envoie des coffres dans les Cadeaux du clan.",
  "Every chest is worth points, set by the clan for each chest and source. Points count toward the weekly goal.": "Chaque coffre vaut des points, fixés par le clan pour chaque coffre et source. Les points comptent pour l’objectif hebdomadaire.",
