  "{pct} of their target on average, over {n} runs": { one: "{pct} de son objectif en moyenne, sur {n} session", other: "{pct} de son objectif en moyenne, sur {n} sessions" },
  "{n} runs had no targets pasted, so they are measured against the median player": { one: "{n} session n'avait pas d'objectifs collés, elle est donc comparée au joueur médian", other: "{n} sessions n'avaient pas d'objectifs collés, elles sont donc comparées au joueur médian" },
  "No finished event run in this timeframe": "Aucune session d'événement terminée sur cette période",
