  "Score": "Score",
  "{n} days in the clan in this timeframe": { one: "{n} jour dans le clan sur cette période", other: "{n} jours dans le clan sur cette période" },
  "No member matches these filters.": "Aucun membre ne correspond à ces filtres.",
  "Page {page} of {pages} · {n} members": { one: "Page {page} sur {pages} · {n} membre", other: "Page {page} sur {pages} · {n} membres" },
  "Goal": "Objectif",
  "{points} from the week of {date}": "{points} à partir de la semaine du {date}",
  "The goal changed in this timeframe: {steps}.": "L'objectif a changé sur cette période : {steps}.",
  "weight {pct}": "poids {pct}",
  "How the score works": "Comment le score est calculé",
  "the share of closed weeks at or above the weekly points goal that applied that week (the Leaderboard goal, now {goal} points).": "la part des semaines terminées où l'objectif hebdo de points en vigueur cette semaine-là est atteint ou dépassé (l'objectif du classement, actuellement {goal} points).",
  "A week that misses it but reaches {near} of it counts as {credit} of a hit.": "Une semaine qui le manque mais en atteint {near} compte pour {credit} d'une réussite.",
  "points each week as a share of that goal, so going over it counts: a week at 150% of the goal lifts the score as much as a {tinman} run at 150% of its target.": "les points de chaque semaine rapportés à cet objectif, donc le dépasser compte : une semaine à 150 % de l'objectif fait monter le score autant qu'une session de {tinman} à 150 % de son objectif.",
  "points in each finished {tinman} run against the target for their guards level, from the targets pasted on Events → Ancients.": "les points de chaque session de {tinman} terminée par rapport à l'objectif de leur niveau de Gardes, d'après les objectifs collés dans Événements → Ancients.",
  "A run with no targets is measured against the median player.": "Une session sans objectifs est comparée au joueur médian.",
  "A run with no targets pasted doesn’t count.": "Une session sans objectifs collés ne compte pas.",
  "It counts toward the score once there are {n} runs with targets in this timeframe.": { one: "Cela compte dans le score dès qu'il y a {n} session avec objectifs sur cette période.", other: "Cela compte dans le score dès qu'il y a {n} sessions avec objectifs sur cette période." },
  "points in each finished run of {events} against the median participant. A run sat out counts as 0.": "les points de chaque session terminée de {events} par rapport au participant médian. Une session manquée compte pour 0.",
  "A week or run only counts if the member was in the clan for all of it. Up to {from} of the goal or target, a share counts as it is; above that, every doubling adds {step}: {twice} scores {twiceScore}, and {capAt} or more scores {cap}, the most one week or run can count, so a single huge week can’t hide empty ones. The columns show the real shares.": "Une semaine ou une session ne compte que si le membre était dans le clan du début à la fin. Jusqu'à {from} de l'objectif, la part compte telle quelle ; au-delà, chaque doublement ajoute {step} : {twice} donne {twiceScore}, et {capAt} ou plus donne {cap}, le maximum qu'une semaine ou une session peut compter, pour qu'une seule semaine énorme ne masque pas les semaines vides. Les colonnes montrent les parts réelles.",
  "A week or run only counts if the member was in the clan for all of it, and one counts for at most {cap}, so a single huge week can’t hide empty ones.": "Une semaine ou une session ne compte que si le membre était dans le clan du début à la fin, et chacune compte au plus pour {cap}, pour qu'une seule semaine énorme ne masque pas les semaines vides.",
  "The score is the weighted average of the parts a member has enough data for. 100% means meeting every expectation; {over} or more is an overachiever, below {under} an underachiever.": "Le score est la moyenne pondérée des parties pour lesquelles le membre a assez de données. 100% signifie remplir toutes les attentes ; {over} ou plus, c'est au-dessus, sous {under}, en dessous.",
  "To be shown, a member needs {n} days in the clan within this timeframe. Time in the clan counts from their first chest, might reading or sighting, whichever is earliest, so a renamed player keeps their old name’s history.": { one: "Pour apparaître, un membre doit avoir {n} jour dans le clan sur cette période. Le temps dans le clan compte depuis son premier coffre, sa première lecture de puissance ou sa première apparition, selon ce qui est le plus ancien : un joueur renommé garde l'historique de son ancien nom.", other: "Pour apparaître, un membre doit avoir {n} jours dans le clan sur cette période. Le temps dans le clan compte depuis son premier coffre, sa première lecture de puissance ou sa première apparition, selon ce qui est le plus ancien : un joueur renommé garde l'historique de son ancien nom." },
