  "When you save, you choose: from today on (chests from earlier days keep their points) or for all history (every recorded chest is rescored — for fixing a wrong value).": "À l'enregistrement, vous choisissez : à partir d'aujourd'hui (les coffres des jours précédents gardent leurs points) ou pour tout l'historique (chaque coffre enregistré est recalculé — pour corriger une valeur erronée).",
