  "edited {when} by {user}": "modifié le {when} par {user}",
  "From game day {day}": "À partir du jour de jeu {day}",
  "No visible change on its own — it keeps some chests at the value they already had.": "Aucun changement visible à lui seul — il maintient certains coffres à la valeur qu'ils avaient déjà.",
  "Applies from game day": "S'applique à partir du jour de jeu",
  "Leave this one out of the change": "Retirer cette valeur du changement",
  "Leave {name} out of the change": "Retirer {name} du changement",
  "Every value is left out — saving removes this change.": "Toutes les valeurs sont retirées — enregistrer supprime ce changement.",
  "Note": "Note",
  "Why the value changed": "Pourquoi la valeur a changé",
  "Copied from {clan} — all history": "Copié depuis {clan} — tout l'historique",
  "Correction — all history": "Correction — tout l'historique",
  "No value changed.": "Aucune valeur n'a changé.",
  "A dated change applies from its game day's reset on; chests from earlier days keep the points they had. A correction to all history rescored every recorded chest, so it is kept as a record only.": "Un changement daté s'applique à partir de la réinitialisation de son jour de jeu ; les coffres des jours précédents gardent leurs points. Une correction de tout l'historique a recalculé chaque coffre enregistré : elle n'est donc conservée qu'à titre de trace.",
  "Dated changes": "Changements datés",
  "No dated changes yet. Values saved “from today on” are listed here.": "Aucun changement daté pour l'instant. Les valeurs enregistrées « à partir d'aujourd'hui » apparaissent ici.",
  "Corrections to all history": "Corrections de tout l'historique",
  "Changes made before this history was kept (November 2026) were applied to all history and are not listed.": "Les changements antérieurs à cet historique (novembre 2026) s'appliquaient à tout l'historique et ne sont pas listés.",
  "{name}: “{value}” isn't a whole number of points.": "{name} : « {value} » n'est pas un nombre entier de points.",
  "Check the value": "Vérifiez la valeur",
  "Pick the game day the change applies from.": "Choisissez le jour de jeu à partir duquel le changement s'applique.",
  "Check the date": "Vérifiez la date",
  "Preview failed": "Échec de l'aperçu",
  "Remove the change from {day}?": "Supprimer le changement du {day} ?",
  "Save the change from {day}?": "Enregistrer le changement à partir du {day} ?",
  "As edited it no longer changes anything, so it is removed.": "Ainsi modifié, il ne change plus rien : il est donc supprimé.",
  "Chests from game day {day} on score these values, until the next change of the same chest.": "Les coffres à partir du jour de jeu {day} reçoivent ces valeurs, jusqu'au prochain changement du même coffre.",
  "Remove change": "Supprimer le changement",
  "Save changes": "Enregistrer",
