  "{n} records": { one: "{n} enregistrement", other: "{n} enregistrements" },
  "Change removed": "Changement supprimé",
  "Change saved": "Changement enregistré",
  "Chests from game day {day} on go back to the values in force before it, until the next change of the same chest.": "Les coffres à partir du jour de jeu {day} reprennent les valeurs en vigueur avant lui, jusqu'au prochain changement du même coffre.",
  "Remove failed": "Échec de la suppression",
  "source value": "valeur de la source",
  "Per clan": "Par clan",
  "Where the points move ({n} lines)": { one: "Où vont les points ({n} ligne)", other: "Où vont les points ({n} lignes)" },
  "…and {n} more lines": { one: "…et {n} ligne de plus", other: "…et {n} lignes de plus" },
  "chest records change": { one: "coffre enregistré modifié", other: "coffres enregistrés modifiés" },
  "points in total": { one: "point au total", other: "points au total" },
  "Chests of <strong>{clan}</strong> already recorded today are rescored; everything before today keeps its points.": "Les coffres de <strong>{clan}</strong> déjà enregistrés aujourd'hui sont recalculés ; tout ce qui précède aujourd'hui garde ses points.",
  "No chest recorded before now changes — chests of <strong>{clan}</strong> from today on score the new values.": "Aucun coffre déjà enregistré ne change — les coffres de <strong>{clan}</strong> à partir d'aujourd'hui reçoivent les nouvelles valeurs.",
  "This joins the change already saved for today, {day}.": "Ceci s'ajoute au changement déjà enregistré pour aujourd'hui, {day}.",
  "Every stored chest record of <strong>{clan}</strong> from these sources gets the new value, whatever day it was earned.": "Chaque enregistrement de coffre de <strong>{clan}</strong> issu de ces sources reçoit la nouvelle valeur, quel que soit le jour où il a été gagné.",
  "No stored chest record of <strong>{clan}</strong> changes.": "Aucun enregistrement de coffre de <strong>{clan}</strong> ne change.",
  "It replaces what the dated changes from {days} set for these chests.": { one: "Elle remplace ce que le changement daté du {days} fixait pour ces coffres.", other: "Elle remplace ce que les changements datés des {days} fixaient pour ces coffres." },
  "Save {n} changes for {clan}?": { one: "Enregistrer {n} changement pour {clan} ?", other: "Enregistrer {n} changements pour {clan} ?" },
  "Apply to": "Appliquer à",
  "From today on": "À partir d'aujourd'hui",
  "Chests from game day {day} on score the new values. Chests from earlier days keep their points.": "Les coffres à partir du jour de jeu {day} reçoivent les nouvelles valeurs. Les coffres des jours précédents gardent leurs points.",
  "All history": "Tout l'historique",
  "Every chest this clan ever recorded is rescored. Use it to fix a value that was wrong.": "Chaque coffre jamais enregistré par ce clan est recalculé. À utiliser pour corriger une valeur erronée.",
  "Note (optional, shown in the history)": "Note (facultative, affichée dans l'historique)",
  "Nothing to save.": "Rien à enregistrer.",
  "No changes": "Aucun changement",
  "Those values are already in place — nothing to save.": "Ces valeurs sont déjà en place — rien à enregistrer.",
  "{n} changes": { one: "{n} changement", other: "{n} changements" },
  "{changes} saved from {day} on · {records} updated · {points} pts": "Enregistré à partir du {day} : {changes} · Mis à jour : {records} · {points} pts",
  "{changes} saved · {records} updated · {points} pts": "Enregistré : {changes} · Mis à jour : {records} · {points} pts",
  "Chest points saved": "Points des coffres enregistrés",
  "You have {n} unsaved changes. Recalculate only uses saved values — use Review & save first (saving updates the stored records itself).": { one: "Vous avez {n} changement non enregistré. Recalculer n'utilise que les valeurs enregistrées — utilisez d'abord Vérifier et enregistrer (l'enregistrement met lui-même à jour les données stockées).", other: "Vous avez {n} changements non enregistrés. Recalculer n'utilise que les valeurs enregistrées — utilisez d'abord Vérifier et enregistrer (l'enregistrement met lui-même à jour les données stockées)." },
  "Save your changes first": "Enregistrez d'abord vos changements",
  "Recalculate failed": "Échec du recalcul",
  "Every stored chest record already matches the current values — saves update records as they are made.": "Chaque coffre enregistré correspond déjà aux valeurs actuelles — chaque enregistrement met les données à jour au fur et à mesure.",
  "Nothing to recalculate": "Rien à recalculer",
  "Recalculate chest points?": "Recalculer les points des coffres ?",
  "These stored records of <strong>{clan}</strong> no longer match the values in force on the day they were earned (usually chests scanned before a value was set). Recalculating brings them in line.": "Ces enregistrements de <strong>{clan}</strong> ne correspondent plus aux valeurs en vigueur le jour où ils ont été gagnés (en général des coffres scannés avant qu'une valeur soit définie). Recalculer les remet en conformité.",
  "Recalculated": "Recalculé",
  "You have {n} unsaved changes. Copying replaces every value, so save or discard them first.": { one: "Vous avez {n} changement non enregistré. La copie remplace toutes les valeurs : enregistrez-le ou annulez-le d'abord.", other: "Vous avez {n} changements non enregistrés. La copie remplace toutes les valeurs : enregistrez-les ou annulez-les d'abord." },
  "There is no other clan to copy values from.": "Il n'y a aucun autre clan depuis lequel copier les valeurs.",
  "Nothing to copy": "Rien à copier",
  "Every chest point value of {clan} is replaced by the other clan's. The other clan is not changed.": "Chaque valeur de points des coffres de {clan} est remplacée par celle de l'autre clan. L'autre clan n'est pas modifié.",
  "Copy values into {clan}": "Copier les valeurs dans {clan}",
  "Copy from": "Copier depuis",
  "Copy {from}'s values into {clan}?": "Copier les valeurs de {from} dans {clan} ?",
  "<strong>{clan}</strong> will pay exactly what <strong>{from}</strong> pays ({n} saved values; anything {from} hasn't set uses the built-in default).": { one: "<strong>{clan}</strong> paiera exactement ce que paie <strong>{from}</strong> ({n} valeur enregistrée ; tout ce que {from} n'a pas défini utilise la valeur par défaut intégrée).", other: "<strong>{clan}</strong> paiera exactement ce que paie <strong>{from}</strong> ({n} valeurs enregistrées ; tout ce que {from} n'a pas défini utilise la valeur par défaut intégrée)." },
  "These stored chest records of {clan} are updated right away. {from} is not changed.": "Ces enregistrements de {clan} sont mis à jour immédiatement. {from} n'est pas modifié.",
  "No stored chest record of {clan} changes. {from} is not changed.": "Aucun enregistrement de {clan} ne change. {from} n'est pas modifié.",
  "The copied values apply to all history, so the {n} dated changes of {clan} go.": { one: "Les valeurs copiées s'appliquent à tout l'historique : le changement daté de {clan} disparaît donc.", other: "Les valeurs copiées s'appliquent à tout l'historique : les {n} changements datés de {clan} disparaissent donc." },
