  "{n} players in the ranking read from the game, through day {day}.": { one: "{n} joueur dans le classement lu dans le jeu, jusqu'au jour {day}.", other: "{n} joueurs dans le classement lu dans le jeu, jusqu'au jour {day}." },
  "{n} players · scores as they stood after day {day}, read from the game.": { one: "{n} joueur · scores après le jour {day}, lus dans le jeu.", other: "{n} joueurs · scores après le jour {day}, lus dans le jeu." },
  "{n} players in the ranking pasted after day {day}.": { one: "{n} joueur dans le classement collé après le jour {day}.", other: "{n} joueurs dans le classement collé après le jour {day}." },
  "{n} players · scores as they stood after day {day} (day {last} is pasted too).": { one: "{n} joueur · scores tels qu'après le jour {day} (le jour {last} est aussi collé).", other: "{n} joueurs · scores tels qu'après le jour {day} (le jour {last} est aussi collé)." },
  "{n} members donated {resource} between {from} and {to}.": { one: "{n} membre a donné de l'{resource} entre le {from} et le {to}.", other: "{n} membres ont donné de l'{resource} entre le {from} et le {to}." },
  "No scores for this run yet — they are read from the game while the event runs.": "Pas encore de scores pour cette édition — ils sont lus dans le jeu pendant l'événement.",
  "Nobody donated {resource} between {from} and {to}.": "Personne n'a donné d'{resource} entre le {from} et le {to}.",
  "The event calendar is unavailable, so this run's dates aren't known.": "Le calendrier des événements est indisponible, les dates de cette édition sont donc inconnues.",
  "No runs to pick from — the event calendar is unavailable and the game has no scores for this event yet.": "Aucune édition à choisir — le calendrier des événements est indisponible et le jeu n'a pas encore de scores pour cet événement.",
  "Could not load the scores.": "Impossible de charger les scores.",
  "Rewards to share": "Récompenses à répartir",
  "The clan's totals": "Les totaux du clan",
  "Clan fragments": "Fragments de clan",
  "Whole numbers; 7.5m and 250k work too.": "Nombres entiers ; 7.5m et 250k fonctionnent aussi.",
  "The Clan Capital ledger could not be read.": "Le registre de la Capitale du clan n'a pas pu être lu.",
  "What the clan wins is credited when the run ends and fills in after the next scan.": "Ce que gagne le clan est crédité à la fin de l'édition et s'affiche ici après le scan suivant.",
  "This run ended before the Clan Capital ledger the scans keep begins ({date}).": "Cette édition s'est terminée avant le début du registre de la Capitale du clan conservé par les scans ({date}).",
  "Nothing the clan won in this run is in the Clan Capital ledger.": "Rien de ce que le clan a gagné dans cette édition ne figure au registre de la Capitale du clan.",
  "What the clan won, credited {when}, holds no {coins} or clan fragments.": "Ce que le clan a gagné, crédité le {when}, ne contient ni {coins} ni fragments de clan.",
  "Use the ledger's totals": "Reprendre les totaux du registre",
  "From the Clan Capital ledger: {items}, credited {when}.": "Du registre de la Capitale du clan : {items}, crédité le {when}.",
  "Distribution": "Répartition",
  "Include all members": "Inclure tous les membres",
  "<strong>{n}</strong> players share": { one: "<strong>{n}</strong> joueur se partage le tout", other: "<strong>{n}</strong> joueurs se partagent le tout" },
  "<strong>{n}</strong> left out": { one: "<strong>{n}</strong> exclu", other: "<strong>{n}</strong> exclus" },
  "{column} total <strong>{total}</strong>": "Total {column} <strong>{total}</strong>",
  "Enter the clan's totals above to see what each player gets.": "Saisissez les totaux du clan ci-dessus pour voir ce que reçoit chaque joueur.",
  "No player matches “{query}”.": "Aucun joueur ne correspond à « {query} ».",
  "No longer on the clan roster — a reward can't reach them. Tick to include anyway.": "N'est plus dans la liste du clan — aucune récompense ne peut lui parvenir. Cochez pour l'inclure quand même.",
  "left the clan": "a quitté le clan",
  "Not matched to a clan member yet": "Pas encore associé à un membre du clan",
  "not matched": "non associé",
  "{n} fragments": { one: "{n} fragment", other: "{n} fragments" },
  "Leave out {name}": "Exclure {name}",
  "Include {name}": "Inclure {name}",
  "Included": "Inclus",
  "<strong>The pots.</strong> What the clan won in the run — the {coins} and clan fragments the game puts in the treasury when it ends — fill in from the Clan Capital ledger. Type over them to share a different amount.": "<strong>Les cagnottes.</strong> Ce que le clan a gagné dans l'édition — les {coins} et fragments de clan que le jeu verse au trésor à la fin — se remplit depuis le registre de la Capitale du clan. Tapez par-dessus pour répartir un autre montant.",
  "<strong>The split.</strong> Each player gets the pot × their score ÷ everyone's total, rounded down. The units left over go one each to the largest remainders, so the parts always add up to the pot.": "<strong>La répartition.</strong> Chaque joueur reçoit la cagnotte × son score ÷ le total de tous, arrondi à l'inférieur. Les unités restantes vont une par une aux plus grands restes, donc les parts font toujours exactement la cagnotte.",
  "<strong>Leaving someone out.</strong> Untick them: they get nothing, and their part is spread over everyone else by score. Who you leave out is remembered in this browser.": "<strong>Exclure quelqu'un.</strong> Décochez-le : il ne reçoit rien et sa part est répartie entre les autres selon leur score. Les exclusions sont mémorisées dans ce navigateur.",
  "<strong>Left the clan.</strong> Players the roster no longer lists start unticked — a reward can only be sent to a member.": "<strong>Partis du clan.</strong> Les joueurs absents de la liste du clan sont décochés au départ — une récompense ne peut être envoyée qu'à un membre.",
  "<strong>{olympus}.</strong> The clan ranking on Events → {olympus}, read from the game, as it stood after the day you pick. The ranking keeps growing through the run, so the last day is the whole run.": "<strong>{olympus}.</strong> Le classement du clan dans Événements → {olympus}, lu dans le jeu, tel qu'après le jour choisi. Le classement grandit tout au long de l'édition, donc le dernier jour couvre l'édition entière.",
  "<strong>{omens}.</strong> {essence} donated during the run, from resource tracking, or the {spoils} damage ranking on Events → {omens}, read from the game.": "<strong>{omens}.</strong> L'{essence} donnée pendant l'édition, d'après le suivi des ressources, ou le classement des dégâts de {spoils} dans Événements → {omens}, lu dans le jeu.",
  "Splits like {link}. Where a leftover fragment could go either way, it may land on a different player.": "Répartit comme {link}. Quand un fragment restant pourrait aller à l'un ou à l'autre, il peut tomber sur un autre joueur.",
  "totalcalculator.org's rewards page": "la page des récompenses de totalcalculator.org",
