  "Restore cancelled": "Restauration annulée",
  "Restoring {label}… this can take a minute on a large backup.": "Restauration de {label}… cela peut prendre une minute pour une grosse sauvegarde.",
  "Clan restore failed": "Échec de la restauration du clan",
