  "<strong>Vault pot.</strong> Each member raids one vault in {event}. Their guards level caps its size: G1 1,000 … G9 8,200 vault points.": "<strong>Cagnotte de Chambre Forte.</strong> Chaque membre attaque une Chambre Forte pendant {event}. Son niveau de gardes en plafonne la taille : G1 1 000 … G9 8 200 points de Chambre Forte.",
  "<strong>What it buys.</strong> The Figurine (summons) and the Tome you pick come first. The Clock gets the rest, up to 120 minutes.": "<strong>Ce qu'elle achète.</strong> La Figurine (invocations) et le Tome choisi passent en premier. Le Clock reçoit le reste, jusqu'à 120 minutes.",
  "<strong>The target.</strong> Every summon is planned as a kill, one {tinman} level higher each time. The clan must score their combined HP plus the Tome bonus.": "<strong>L'objectif.</strong> Chaque invocation est planifiée comme une élimination, un niveau de {tinman} plus haut à chaque fois. Le clan doit marquer la somme de leurs PV plus le bonus du Tome.",
  "<strong>The split.</strong> Each tier gets a fixed weight (G9 = 2.25× G8, and T9 = 1.75× G9). The ratios are a planning convention, not game data.": "<strong>La répartition.</strong> Chaque palier a un poids fixe (G9 = 2,25× G8, et T9 = 1,75× G9). Ces ratios sont une convention de planification, pas des données du jeu.",
  "<strong>Summons 7 and 8</strong> are only offered while a seasonal kingdom runs.": "<strong>Les invocations 7 et 8</strong> ne sont proposées que pendant un royaume saisonnier.",
  "Matches {link}, rebuilt from its outputs.": "Correspond à {link}, reconstruit à partir de ses résultats.",
  "totalcalculator.org's Ancient planner": "l'Ancient planner de totalcalculator.org",
  // pages/triumphal.js
  "The Triumphal Chests could not be loaded.": "Les coffres triomphaux n’ont pas pu être chargés.",
  "Total triumphal chests": "Total des coffres triomphaux",
  "Members with triumphals": "Membres avec des coffres triomphaux",
  "Total points": "Total des points",
  "No triumphal chests in this period.": "Aucun coffre triomphal sur cette période.",
  "Triumphal chests come from in-game package purchases. Each chest is worth one third of its package value, shown rounded to a whole number — Magic ≈83, Precious ≈33, Golden ≈17, Silver ≈7, Bronze ≈3, Wooden ≈2 — so a full set of three sums back to the package value (3 Golden = 50). These points are tracked separately from the main leaderboard.": "Les coffres triomphaux proviennent d'achats de packs en jeu. Chaque coffre vaut un tiers de la valeur de son pack, arrondie à l'entier — Magic ≈83, Precious ≈33, Golden ≈17, Silver ≈7, Bronze ≈3, Wooden ≈2 — de sorte qu'un ensemble complet de trois redonne la valeur du pack (3 Golden = 50). Ces points sont suivis séparément du classement principal.",
  "Recent chests": "Coffres récents",
