  "Create, modify, and remove user accounts. Roles control which pages a user can access.": "Créez, modifiez et supprimez des comptes utilisateurs. Les rôles déterminent les pages auxquelles un utilisateur a accès.",
  "Manage user accounts for your clan. You can grant the User and Admin roles; only superadmins manage instance-wide accounts.": "Gérez les comptes utilisateurs de votre clan. Vous pouvez attribuer les rôles Utilisateur et Admin ; seuls les superadmins gèrent les comptes globaux de l'instance.",
  "Players get their account with a code from the game chat (Clans → Account invites via chat): it is linked to their player, and its role follows their rank — the {leader} and {superior} ranks are admins.": "Les joueurs obtiennent leur compte avec un code du chat du jeu (Clans → Invitations de compte par chat) : il est lié à leur joueur et son rôle suit leur rang — les rangs {leader} et {superior} sont admins.",
  "New accounts are created in the clan selected in the header. Choosing role <strong>Super Admin</strong> drops the clan — superadmins are cross-clan.": "Les nouveaux comptes sont créés dans le clan sélectionné dans l'en-tête. Choisir le rôle <strong>Superadmin</strong> retire le clan — les superadmins sont multi-clans.",
